from pathlib import Path
import hashlib,json,numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parent;out={}
for device in ["BFPT","CND1"]:
 r=ROOT/"type_diverse_data"/device;d=np.load(r/f"{device}_fault_dataset.npz",allow_pickle=True);m={s:pd.read_csv(r/f"{s}_manifest.csv") for s in ["train","val","test"]};dates={s:set(v.date.astype(str)) for s,v in m.items()};h={s:{hashlib.sha256(x.tobytes()).hexdigest() for x in d[f"X_{s}"]} for s in ["train","val","test"]};out[device]={"nodes":int(d["X_train"].shape[1]),"samples":{s:int(len(d[f"y_{s}"])) for s in ["train","val","test"]},"class_counts":{s:np.bincount(d[f"y_{s}"]).tolist() for s in ["train","val","test"]},"date_overlap_train_val":sorted(dates["train"]&dates["val"]),"date_overlap_train_test":sorted(dates["train"]&dates["test"]),"date_overlap_val_test":sorted(dates["val"]&dates["test"]),"exact_duplicate_train_val":len(h["train"]&h["val"]),"exact_duplicate_train_test":len(h["train"]&h["test"]),"exact_duplicate_val_test":len(h["val"]&h["test"])}
(ROOT/"type_diverse_deliverables").mkdir(parents=True,exist_ok=True);(ROOT/"type_diverse_deliverables"/"dataset_leakage_audit.json").write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding="utf-8");print(json.dumps(out,ensure_ascii=False,indent=2))
